update public.docs set data = jsonb_set(jsonb_set(data, '{Departments}', '["الإدارة العامة","الموارد البشرية","المالية والمحاسبة","المبيعات والتسويق","المشتريات","العمليات / الإنتاج","تقنية المعلومات","الخدمات المساندة","أمن المعلومات","الجودة والسلامة","الشؤون القانونية والامتثال","إدارة المخاطر"]'::jsonb), '{Jobs}', '["المدير العام","مدير إدارة الموارد البشرية","المدير المالي","مدير المبيعات والتسويق","سائق","أخصائي موارد بشرية","مدير تقنية المعلومات","مدير العمليات","فني","مندوب مبيعات","محاسب","عامل","حارس أمن","مدير المشتريات","مدير الخدمات المساندة","مهندس","مدير أمن المعلومات","مدير الجودة والسلامة","مدير الشؤون القانونية والامتثال","مدير المخاطر","رئيس قسم 1","مشرف موارد بشرية","رئيس حسابات 1","مشرف محاسبة","محاسب مساعد","مدير منطقة 1","مشرف مبيعات","أخصائي تسويق","مشرف مشتريات","مدير مصنع 1","مشرف إنتاج","عامل إنتاج","مشغل آلة","فني عمليات","مشرف دعم فني","مدير خدمات 1","مشرف خدمات","عامل خدمات","مشرف أمن سيبراني","مشرف جودة","مشرف قانوني","مشرف مخاطر"]'::jsonb) where tenant_id = (select id from public.tenants where code='elhadry') and key = 'lists';